["/rc/editors/advanced.lua"] = [=[
-- A much better editor.

local rc = require("rc")
local keys = require("keys")
local term = require("term")
local colors = require("colors")
local settings = require("settings")
local textutils = require("textutils")

local args = {...}

local type_colors = {
  separator = colors[settings.get("edit.color_separator") or "lightBlue"],
  operator = colors[settings.get("edit.color_operator") or "lightGray"],
  keyword = colors[settings.get("edit.color_keyword") or "orange"],
  boolean = colors[settings.get("edit.color_boolean") or "purple"],
  comment = colors[settings.get("edit.color_comment") or "gray"],
  builtin = colors[settings.get("edit.color_global") or "lime"],
  string = colors[settings.get("edit.color_string") or "red"],
  number = colors[settings.get("edit.color_number") or "magenta"]
}

local lines = {}
local linesDraw = {}
local highlighted_source = {}
local run, menu = true, false
local cx, cy = 1, 1
local scroll = 0
local hscroll = 0
local scroll_offset = settings.get("edit.scroll_offset") or 3
local scroll_increment = 0
local scroll_factor = settings.get("edit.scroll_factor") or 8
local unsaved, changed = false, true
local file = args[1] or ".new"
local status = "Press Ctrl for menu"

if args[1] then
  local handle = io.open(args[1], "r")

  if handle then
    for line in handle:lines() do
      lines[#lines+1] = line
    end
    handle:close()
  end
end

if not lines[1] then lines[1] = "" end

local win = require("window").create(term.current(), 1, 1, term.getSize())

local drawn, drawn_status, drawn_w, drawn_h, drawn_scroll = {}, nil, nil, nil, nil
local function same_line(a, b)
  if a == b then return true end
  if not a or not b or #a ~= #b then return false end
  for i = 1, #a do if a[i] ~= b[i] then return false end end
  return true
end
local function redraw()
  local w, h = term.getSize()
  scroll_increment = math.floor(h/scroll_factor)
  if w ~= drawn_w or h ~= drawn_h then
    win.reposition(1, 1, w, h)
    drawn, drawn_status = {}, nil
  elseif drawn_scroll ~= hscroll then drawn = {} end
  drawn_w, drawn_h, drawn_scroll = w, h, hscroll
  for i=1, h - 1, 1 do
    local line = linesDraw[i] or false
    if not same_line(drawn[i], line) then
      win.setCursorPos(1 - hscroll, i)
      win.setTextColor(colors.white)
      win.clearLine()
      if line then
        for t=1, #line, 1 do
          local item = line[t]
          if type(item) == "number" then win.setTextColor(item)
          else win.write(item) end
        end
      end
      drawn[i] = line
    end
  end
  if drawn_status ~= status then
    win.setCursorPos(1, h)
    win.clearLine()
    win.setTextColor(type_colors.accent or colors.yellow)
    win.write(status)
    drawn_status = status
  end
  win.setTextColor(colors.white)
  win.setCursorPos(math.min(w, cx), cy - scroll)
  win.setCursorBlink(true)
end

local syntax = require("edit.syntax")
  .new("/rc/modules/main/edit/syntax/lua.lua")

local function rehighlight()
  local line = {}
  linesDraw = {}
  local _, h = term.getSize()
  highlighted_source = {}
  for i = 1, h - 1 do highlighted_source[i] = lines[scroll+i] or "" end
  local text = table.concat(lines, "\n", scroll+1,
    math.min(#lines, scroll+h+1)) or ""
  for token, ttype in syntax(text) do
    if token == "\n" then
      linesDraw[#linesDraw+1] = line
      line = {}

    else
      repeat
        local bit = token:find("\n")
        local nl = not not bit
        local chunk = token:sub(1, bit or #token)
        token = token:sub(#chunk+1)
        line[#line+1] = type_colors[ttype] or colors.white
        line[#line+1] = chunk
        if nl then
          linesDraw[#linesDraw+1] = line
          line = {}
        end
      until #token == 0
    end
  end

  if #line > 0 then
    linesDraw[#linesDraw+1] = line
  end
end

-- Text echoes immediately. Syntax waits for a short idle period instead of
-- running the guest pattern engine synchronously after every character.
local highlight_timer
local function delayed_highlight(event, id)
  if event == "timer" and id == highlight_timer then
    highlight_timer = nil
    rehighlight()
    return true
  end
end
local function save()
  if file == ".new" then
    local _, h = term.getSize()
    term.setCursorPos(1, h)
    textutils.coloredWrite(colors.yellow, "filename: ")
    file = term.read()
  end

  local handle, err = io.open(file, "w")
  if not handle then
    status = err

  else
    for i=1, #lines, 1 do
      handle:write(lines[i] .. "\n")
    end
    handle:close()

    status = "Saved to " .. file
    unsaved = false
  end
end

local function processInput()
  local event, id = rc.pullEvent()
  if delayed_highlight(event, id) then return end

  local w, h = term.getSize()

  if event == "char" then
    local line = lines[cy]
    unsaved = true

    if cx > #line then
      line = line .. id

    elseif cx == 1 then
      line = id .. line

    else
      line = line:sub(0, cx-1) .. id .. line:sub(cx)
    end

    cx = cx + 1
    lines[cy] = line
    changed = true

  elseif event == "paste" then
    id = id:gsub("\r\n", "\n"):gsub("\r", "\n")
    unsaved, changed = true, true
    local start = 1
    while true do
      local newline = id:find("\n", start, true)
      local text = newline and id:sub(start, newline - 1) or id:sub(start)
      local line = lines[cy]
      line = line:sub(1, cx - 1) .. text .. line:sub(cx)
      cx = cx + #text
      lines[cy] = line
      if not newline then break end
      lines[cy] = line:sub(1, cx - 1)
      table.insert(lines, cy + 1, line:sub(cx))
      cy, cx, start = cy + 1, 1, newline + 1
    end
    scroll = math.max(0, math.min(#lines - h + 1, cy - h + scroll_offset))
    hscroll = math.max(0, cx - w)

  elseif event == "key" then
    id = keys.getName(id)

    if id == "backspace" then
      local line = lines[cy]
      unsaved = true

      if cx == 1 and cy > 1 then
        local previous = table.remove(lines, cy - 1)
        cy = cy - 1
        cx = #previous + 1
        line = previous .. line

      else
        if #line > 0 then
          if cx > #line then
            cx = cx - 1
            line = line:sub(1, -2)

          elseif cx > 1 then
            line = line:sub(0, cx - 2) .. line:sub(cx)
            cx = cx - 1
          end
        end
      end

      lines[cy] = line
      changed = true

    elseif id == "enter" then
      if cx == 1 then
        table.insert(lines, cy, "")

      elseif cx > #lines[cy] then
        table.insert(lines, cy+1, "")

      else
        local line = lines[cy]
        local before, after = line:sub(0, cx - 1), line:sub(cx)
        lines[cy] = before
        table.insert(lines, cy + 1, after)
      end

      cy = cy + 1
      cx = 1

      changed = true

    elseif id == "up" then
      if cy > 1 then
        cy = cy - 1
        if cy - scroll < scroll_offset then
          local old_scroll = scroll
          scroll = math.max(0, scroll - scroll_increment)
          if scroll < old_scroll then
            rehighlight()
          end
        end
      end

      cx = math.min(cx, #lines[cy] + 1)

    elseif id == "down" then
      if cy < #lines then
        cy = math.min(#lines, cy + 1)

        if cy - scroll > h - scroll_offset then
          local old_scroll = scroll
          scroll = math.max(0, math.min(#lines - h + 1,
            scroll + scroll_increment))
          if scroll > old_scroll then
            rehighlight()
          end
        end
      end

      cx = math.min(cx, #lines[cy] + 1)

    elseif id == "left" then
      if cx > 1 then
        cx = cx - 1
      end

      hscroll = math.max(0, cx - w)

    elseif id == "right" then
      if cx < #lines[cy] + 1 then
        cx = cx + 1
      end

      hscroll = math.max(0, cx - w)

    elseif id == "leftCtrl" or id == "rightCtrl" then
      status = "S:save  E:exit"
      menu = true
    end
  end
end

local function processMenuInput()
  local event, id = rc.pullEvent()
  if delayed_highlight(event, id) then return end

  if event == "char" then
    if id:lower() == "e" then
      if unsaved and menu ~= 2 then
        status = "Lose unsaved work? E:yes C:no"
        menu = 2
      else
        term.at(1, 1).clear()
        run = false
      end

    elseif id:lower() == "c" and menu == 2 then
      menu = false

    elseif id:lower() == "s" then
      save()
      menu = false
    end

  elseif event == "key" then
    id = keys.getName(id)

    if id == "leftCtrl" or id == "rightCtrl" then
      status = "Press Ctrl for menu"
      menu = false
    end
  end
end

local initialized = false
while run do
  if changed then
    if not initialized then rehighlight(); initialized = true
    else
      local _, h = term.getSize()
      for i = 1, h - 1 do
        local text = lines[scroll+i] or ""
        if highlighted_source[i] ~= text then
          linesDraw[i] = text ~= "" and {colors.white, text} or false
          highlighted_source[i] = text
        end
      end
      if highlight_timer then rc.cancelTimer(highlight_timer) end
      highlight_timer = rc.startTimer(0.2)
    end
    changed = false
  end
  redraw()
  if menu then
    processMenuInput()
  else
    processInput()
  end
end
if highlight_timer then rc.cancelTimer(highlight_timer) end
]=],
["/rc/editors/basic.lua"] = [=[
-- editor

local args = {...}

local rc = require("rc")
local keys = require("keys")
local term = require("term")
local shell = require("shell")
local colors = require("colors")
local settings = require("settings")
local textutils = require("textutils")

local scroll_offset = settings.get("edit.scroll_offset")

local state = {
  file = args[1] or ".new",
  unsaved = false,
  scroll = 0,
  hscroll = 0,
  lines = {""},
  status = "Press Control for menu",
  cx = 1,
  cy = 1,
}

if args[1] then
  local path = shell.resolve(args[1])
  local handle = io.open(path)
  state.file = path

  if handle then
    state.lines = {}

    for line in handle:lines() do
      state.lines[#state.lines+1] = line
    end

    handle:close()

    if not state.lines[1] then state.lines[1] = "" end
  end
end

local drawn, drawn_status, drawn_w, drawn_h = {}, nil, nil, nil
local function redraw()
  local w, h = term.getSize()
  if w ~= drawn_w or h ~= drawn_h then drawn, drawn_status = {}, nil end
  drawn_w, drawn_h = w, h

  for i=1, h - 1, 1 do
    local to_write = state.lines[state.scroll + i] or ""
    if state.cx > w then
      to_write = to_write:sub(state.cx - (w-1))
    end
    if drawn[i] ~= to_write then
      term.at(1, i).clearLine()
      term.write(to_write)
      drawn[i] = to_write
    end
  end

  if drawn_status ~= state.status then
    term.at(1, h).clearLine()
    textutils.coloredWrite(colors.yellow, state.status, colors.white)
    drawn_status = state.status
  end

  term.setCursorPos(math.min(w, state.cx), state.cy - state.scroll)
end

local run, menu = true, false

local function save()
  if state.file == ".new" then
    local _, h = term.getSize()
    term.setCursorPos(1, h)
    textutils.coloredWrite(colors.yellow, "filename: ", colors.white)
    state.file = term.read()
  end

  local handle, err = io.open(state.file, "w")
  if not handle then
    state.status = err
  else
    for i=1, #state.lines, 1 do
      handle:write(state.lines[i] .. "\n")
    end
    handle:close()
    state.status = "Saved to " .. state.file
    state.unsaved = false
  end
end

local function processMenuInput()
  local event, id = rc.pullEvent()

  if event == "char" then
    if id:lower() == "e" then
      if state.unsaved and menu ~= 2 then
        state.status = "Lose unsaved work? E:yes C:no"
        menu = 2
      else
        term.at(1, 1).clear()
        run = false
      end

    elseif id:lower() == "c" and menu == 2 then
      menu = false

    elseif id:lower() == "s" then
      save()
      menu = false
    end

  elseif event == "key" then
    id = keys.getName(id)

    if id == "leftCtrl" or id == "rightCtrl" then
      state.status = "Press Control for menu"
      menu = false
    end
  end
end

local function processInput()
  local event, id = rc.pullEvent()

  local _, h = term.getSize()

  if event == "char" then
    local line = state.lines[state.cy]
    state.unsaved = true
    if state.cx > #line then
      line = line .. id

    elseif state.cx == 1 then
      line = id .. line

    else
      line = line:sub(0, state.cx-1)..id..line:sub(state.cx)
    end
    state.cx = state.cx + 1

    state.lines[state.cy] = line

  elseif event == "paste" then
    id = id:gsub("\r\n", "\n"):gsub("\r", "\n")
    state.unsaved = true
    local start = 1
    while true do
      local newline = id:find("\n", start, true)
      local text = newline and id:sub(start, newline - 1) or id:sub(start)
      local line = state.lines[state.cy]
      line = line:sub(1, state.cx - 1) .. text .. line:sub(state.cx)
      state.cx = state.cx + #text
      state.lines[state.cy] = line
      if not newline then break end
      state.lines[state.cy] = line:sub(1, state.cx - 1)
      table.insert(state.lines, state.cy + 1, line:sub(state.cx))
      state.cy, state.cx, start = state.cy + 1, 1, newline + 1
    end
    state.scroll = math.max(0, math.min(#state.lines - h + 1, state.cy - h + scroll_offset))

  elseif event == "key" then
    id = keys.getName(id)

    if id == "backspace" then
      local line = state.lines[state.cy]
      state.unsaved = true
      if state.cx == 1 and state.cy > 1 then
        local previous = table.remove(state.lines, state.cy - 1)
        state.cy = state.cy - 1
        state.cx = #previous + 1
        line = previous .. line
      else
        if #line > 0 then
          if state.cx > #line then
            state.cx = state.cx - 1
            line = line:sub(1, -2)

          elseif state.cx > 1 then
            line = line:sub(0, state.cx - 2) .. line:sub(state.cx)
            state.cx = state.cx - 1

          end

        end
      end
      state.lines[state.cy] = line

    elseif id == "enter" then
      if state.cx == 1 then
        table.insert(state.lines, state.cy, "")
      elseif state.cx > #state.lines[state.cy] then
        table.insert(state.lines, state.cy + 1, "")
      else
        local line = state.lines[state.cy]
        local before, after = line:sub(0, state.cx - 1), line:sub(state.cx)
        state.lines[state.cy] = before
        table.insert(state.lines, state.cy + 1, after)
      end

      state.cy = state.cy + 1
      state.cx = 1

    elseif id == "up" then
      if state.cy > 1 then
        state.cy = state.cy - 1
        if state.cy - state.scroll < scroll_offset then
          state.scroll = math.max(0, state.cy - scroll_offset)
        end
      end

      state.cx = math.min(state.cx, #state.lines[state.cy] + 1)

    elseif id == "down" then
      if state.cy < #state.lines then
        state.cy = state.cy + 1

        if state.cy - state.scroll > h - scroll_offset then
          state.scroll = math.max(0, math.min(#state.lines - h + 1,
            state.cy - h + scroll_offset))
        end
      end

      state.cx = math.min(state.cx, #state.lines[state.cy] + 1)

    elseif id == "left" then
      if state.cx > 1 then
        state.cx = state.cx - 1
      end

    elseif id == "right" then
      if state.cx < #state.lines[state.cy] + 1 then
        state.cx = state.cx + 1
      end

    elseif id == "leftCtrl" or id == "rightCtrl" then
      state.status = "S:save  E:exit"
      menu = true

    end
  end
end

term.clear()
while run do
  term.setCursorBlink(false)
  redraw()
  term.setCursorBlink(true)
  if menu then
    processMenuInput()
  else
    processInput()
  end
end
